CREATE TABLE IF NOT EXISTS "cliente" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"nome" VARCHAR(150) NOT NULL,
	"cpf" VARCHAR(20) NOT NULL UNIQUE,
	"telefone" VARCHAR(20),
	"email" VARCHAR(255),
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "receita" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"cliente_id" INTEGER NOT NULL,
	"nome_medico" VARCHAR(150),
	"crm" VARCHAR(30),
	"data" DATE NOT NULL,
	"od_esferico" NUMERIC(5,2),
	"od_cilindrico" NUMERIC(5,2),
	"od_eixo" NUMERIC(5,2),
	"od_dnp" NUMERIC(5,2),
	"od_adicao" NUMERIC(5,2),
	"oe_esferico" NUMERIC(5,2),
	"oe_cilindrico" NUMERIC(5,2),
	"oe_eixo" NUMERIC(5,2),
	"oe_dnp" NUMERIC(5,2),
	"oe_adicao" NUMERIC(5,2),
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "produto" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"nome" VARCHAR(255) NOT NULL,
	"sku" VARCHAR(30) NOT NULL UNIQUE,
	"descricao" VARCHAR(255),
	"estoque" INTEGER NOT NULL CHECK(estoque>=0),
	"valor_unitario" NUMERIC(19,4) NOT NULL CHECK(valor_unitario>=0),
	"categoria_id" INTEGER NOT NULL,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "categoria_produto" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"nome" VARCHAR(150) NOT NULL,
	"descricao" VARCHAR(255),
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "funcionario" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"nome" VARCHAR(150) NOT NULL,
	"cpf" VARCHAR(20) NOT NULL UNIQUE,
	"telefone" VARCHAR(30),
	"email" VARCHAR(255),
	"usuario_id" INTEGER NOT NULL UNIQUE,
	"cargo_id" INTEGER NOT NULL,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "cargo" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"nome" VARCHAR(150) NOT NULL,
	"descricao" VARCHAR(255),
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "venda" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"valor_total" NUMERIC(19,4) NOT NULL CHECK(valor_total>=0),
	"desconto" NUMERIC(19,4) NOT NULL DEFAULT 0 CHECK(desconto>=0),
	"data_hora" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	"cliente_id" INTEGER NOT NULL,
	"funcionario_id" INTEGER NOT NULL,
	"forma_pagamento_id" INTEGER NOT NULL,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "forma_pagamento" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"nome" VARCHAR(50) NOT NULL,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "produto_vendido" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"quantidade" INTEGER NOT NULL CHECK(quantidade>0),
	"valor_unitario" NUMERIC(19,4) NOT NULL CHECK(valor_unitario>=0),
	"produto_id" INTEGER NOT NULL,
	"venda_id" INTEGER NOT NULL,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "usuario" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"nome_usuario" VARCHAR(100) NOT NULL UNIQUE,
	"senha" VARCHAR(255) NOT NULL,
	"ativo" BOOLEAN NOT NULL DEFAULT TRUE,
	PRIMARY KEY("id")
);

ALTER TABLE "produto"
ADD FOREIGN KEY("categoria_id") REFERENCES "categoria_produto"("id")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "produto_vendido"
ADD FOREIGN KEY("produto_id") REFERENCES "produto"("id")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "produto_vendido"
ADD FOREIGN KEY("venda_id") REFERENCES "venda"("id")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "venda"
ADD FOREIGN KEY("forma_pagamento_id") REFERENCES "forma_pagamento"("id")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "venda"
ADD FOREIGN KEY("funcionario_id") REFERENCES "funcionario"("id")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "venda"
ADD FOREIGN KEY("cliente_id") REFERENCES "cliente"("id")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "funcionario"
ADD FOREIGN KEY("cargo_id") REFERENCES "cargo"("id")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "receita"
ADD FOREIGN KEY("cliente_id") REFERENCES "cliente"("id")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "funcionario"
ADD FOREIGN KEY("usuario_id") REFERENCES "usuario"("id")
ON UPDATE NO ACTION ON DELETE NO ACTION;